using OpenBackup;
var root = Path.Combine(Path.GetTempPath(), "openbackup-" + Guid.NewGuid().ToString("N")); var source = Path.Combine(root, "source"); var destination = Path.Combine(root, "snapshots"); Directory.CreateDirectory(source); File.WriteAllText(Path.Combine(source, "notes.txt"), "important");
var snapshot = BackupEngine.CreateSnapshot(source, destination); if (snapshot.Files.Count != 1 || !BackupEngine.VerifySnapshot(Path.Combine(destination, snapshot.Id))) throw new Exception("Fresh snapshot did not verify."); File.AppendAllText(Path.Combine(destination, snapshot.Id, "notes.txt"), "changed"); if (BackupEngine.VerifySnapshot(Path.Combine(destination, snapshot.Id))) throw new Exception("Tampered snapshot verified incorrectly."); Directory.Delete(root, true); Console.WriteLine("PASS: snapshot creation, manifest verification, and tamper detection");
